import React, { useEffect, useRef } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faEnvelope } from "@fortawesome/free-solid-svg-icons";
import {
  faGithub,
  faLinkedin,
  faMedium,
  faStackOverflow,
} from "@fortawesome/free-brands-svg-icons";
import { Box, HStack } from "@chakra-ui/react";

const socials = [
  {
    icon: faEnvelope,
    url: "Nick: nikitaburalek1@gmail.com",
  },
  {
    icon: faGithub,
    url: "https://github.com/Baichau",
  },
  {
    icon: faLinkedin,
    url: "https://www.linkedin.com/in/nick-babichau-060289336",
  },
  {
    icon: faMedium,
    url: "https://medium.com/@nikitaburalek1",
  },
  {
    icon: faStackOverflow,
    url: "https://stackoverflow.com/users/33015385/%d0%9d%d0%b8%d0%ba%d0%b8%d1%82%d0%b0-%d0%91%d0%b0%d1%80%d1%81",
  },
];

const Header = () => {
  const handleClick = (anchor) => () => {
    const id = `${anchor}-section`;
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
    }
  };

  return (
    <Box
      position="fixed"
      top={0}
      left={0}
      right={0}
      translateY={0}
      transitionProperty="transform"
      transitionDuration=".3s"
      transitionTimingFunction="ease-in-out"
      backgroundColor="#18181b"
    >
      <Box color="white" maxWidth="1280px" margin="0 auto">
        <HStack
          px={16}
          py={4}
          justifyContent="space-between"
          alignItems="center"
        >
          <nav>
            {/* Add social media links based on the `socials` data */}
          </nav>
          <nav>
            <HStack spacing={8}>
              {socials.map((social, index) => (
                <a
                  key={index}
                  href={socials.url}
                  target="_blank"
                >
                  <FontAwesomeIcon icon={socials.icon} sixe="2x"/>
              </a>
              ))}
            </HStack>
          </nav>
        </HStack>
      </Box>
    </Box>
  );
};
export default Header;
